package drain

import (
	"context"
	_ "embed"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
)

// Go embed paths cannot reach a sibling module. The committed copy is regenerated by
// tools/tillr-loop/sync-adapter.py and both module suites check it against its source.
//
//go:embed tillr-loop.py
var builtAdapter string

var adapterBuildOnce sync.Once
var adapterBuildName string

func stepBuildEnv() string {
	adapterBuildOnce.Do(func() { adapterBuildName = ReadBuildStamp().String() })
	return "TILLR_LOOP_ADAPTER_BUILD=" + adapterBuildName
}

// builtAdapterProgram selects the adapter shipped inside the running drain binary.
// The keeper passes the same command word for its step programs.
const builtAdapterProgram = "builtin:tillr-loop"

// standardAdapterArg recognizes the built-in command and, for older configurations,
// the standard script under this loop's root. Other programs run as configured.
func (s *ProcessSteps) standardAdapterArg(argv []string) int {
	if len(argv) == 0 {
		return -1
	}
	if argv[0] == builtAdapterProgram {
		return 0
	}
	if s.Root == "" {
		return -1
	}
	standard, err := filepath.Abs(filepath.Join(s.Root, "tools", "tillr-loop", "tillr-loop"))
	if err != nil {
		return -1
	}
	// Resolve symlinks when available, while retaining lexical matching after a landing
	// removes the source. Runtime execution must not depend on that file's continued existence.
	resolve := func(p string) string {
		if resolved, err := filepath.EvalSymlinks(p); err == nil {
			return resolved
		}
		return filepath.Clean(p)
	}
	standard = resolve(standard)
	matches := func(arg string) bool {
		path := arg
		if !filepath.IsAbs(path) {
			path = filepath.Join(s.Root, path)
		}
		path, err := filepath.Abs(path)
		return err == nil && resolve(path) == standard
	}
	if matches(argv[0]) {
		return 0
	}
	if !strings.HasPrefix(filepath.Base(argv[0]), "python") {
		return -1
	}
	// Python options may precede the script. A module or inline command is not a
	// script invocation, even if one of its data arguments happens to name the adapter.
	for i := 1; i < len(argv); i++ {
		switch argv[i] {
		case "-c", "-m", "-":
			return -1
		case "-W", "-X":
			i++
		case "--":
			if i+1 < len(argv) && matches(argv[i+1]) {
				return i + 1
			}
			return -1
		default:
			if !strings.HasPrefix(argv[i], "-") {
				if matches(argv[i]) {
					return i
				}
				return -1
			}
		}
	}
	return -1
}

// stepCommand feeds the build's adapter to Python on stdin rather than reading or
// writing an adapter in the live checkout. The interpreter and all remaining flags stay
// as configured. Command spans show '-' for the build-provided script; startup names it.
func (s *ProcessSteps) stepCommand(ctx context.Context, argv []string, env []string) *exec.Cmd {
	argv = append([]string(nil), argv...)
	index := s.standardAdapterArg(argv)
	if index == 0 {
		argv = append([]string{"python3", "-"}, argv[1:]...)
	} else if index > 0 {
		argv[index] = "-"
	}
	cmd := exec.CommandContext(ctx, argv[0], argv[1:]...)
	cmd.Env = append(withoutProcessEnv(os.Environ(), "TILLR_LOOP_ADAPTER_BUILD"), env...)
	cmd.Env = append(cmd.Env, stepBuildEnv())
	if index >= 0 {
		cmd.Stdin = strings.NewReader(builtAdapter)
	}
	return cmd
}
